-- ============================================================
-- FieldCheck · Migration 0005 — Seed do catálogo padrão
-- GERADO AUTOMATICAMENTE por scripts/gen-seed.mjs — não editar à mão.
-- Fonte: Programa_Inspecoes_Canteiro.xlsx (aba Checklists).
-- 27 checklists / 263 itens. empresa_id = NULL (catálogo do sistema).
-- Idempotente: UUIDs determinísticos + ON CONFLICT (id) DO UPDATE.
-- ============================================================
begin;

on conflict (id) do update set
  area = excluded.area, referencia = excluded.referencia,
  nome = excluded.nome, ativo = true;

on conflict (id) do update set
  ordem = excluded.ordem, texto = excluded.texto, criterio = excluded.criterio;

commit;
